// Builds src/data/world-map.js: every country's outline as an SVG path, for the
// world map on the home page.
//
// Source: Natural Earth's 1:110m countries (public domain), as packaged by the
// world-atlas npm package (ISC licence, copyright Michael Bostock; notice kept
// in the generated file). Download countries-110m.json from
// https://cdn.jsdelivr.net/npm/world-atlas@2.0.2/countries-110m.json, then run:
//   node scripts/build-world.mjs path/to/countries-110m.json
//
// Projection: Equal Earth (Šavrič, Patterson and Jenny, 2018), which keeps the
// continents at their true relative sizes. Antarctica is left out.
import { readFileSync, writeFileSync } from "node:fs";

const file = process.argv[2];
if (!file) {
  console.error("usage: node scripts/build-world.mjs countries-110m.json");
  process.exit(1);
}
const topo = JSON.parse(readFileSync(file, "utf8"));
const [sx, sy] = topo.transform.scale;
const [tx, ty] = topo.transform.translate;

// Arcs are stored as quantised steps; turn each into [lon, lat] points.
const arcs = topo.arcs.map((arc) => {
  let x = 0;
  let y = 0;
  return arc.map(([dx, dy]) => {
    x += dx;
    y += dy;
    return [x * sx + tx, y * sy + ty];
  });
});
const ring = (indexes) => {
  const pts = [];
  for (const i of indexes) {
    const a = i < 0 ? [...arcs[~i]].reverse() : arcs[i];
    pts.push(...(pts.length ? a.slice(1) : a));
  }
  return pts;
};

// Equal Earth.
const A1 = 1.340264, A2 = -0.081106, A3 = 0.000893, A4 = 0.003796, M = Math.sqrt(3) / 2;
function project([lon, lat]) {
  const l = (lon * Math.PI) / 180;
  const t = Math.asin(M * Math.sin((lat * Math.PI) / 180));
  const t2 = t * t, t6 = t2 * t2 * t2;
  const x = (2 * Math.sqrt(3) * l * Math.cos(t)) / (3 * (A1 + 3 * A2 * t2 + t6 * (7 * A3 + 9 * A4 * t2)));
  const y = t * (A1 + A2 * t2 + t6 * (A3 + A4 * t2));
  return [x, y];
}

// Fit the projected world (without Antarctica) into a 1000-wide box.
const geoms = topo.objects.countries.geometries.filter((g) => g.id !== "010");
const polys = (g) => (g.type === "Polygon" ? [g.arcs] : g.type === "MultiPolygon" ? g.arcs : []);
let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
for (const g of geoms) for (const p of polys(g)) for (const r of p) for (const pt of ring(r)) {
  const [x, y] = project(pt);
  minX = Math.min(minX, x); maxX = Math.max(maxX, x); minY = Math.min(minY, y); maxY = Math.max(maxY, y);
}
const W = 1000;
const k = W / (maxX - minX);
const H = Math.round((maxY - minY) * k);
const toSvg = (pt) => {
  const [x, y] = project(pt);
  return [((x - minX) * k).toFixed(1), ((maxY - y) * k).toFixed(1)];
};

const countries = geoms.map((g) => {
  let d = "";
  let best = null;
  for (const p of polys(g)) {
    // France's outline includes French Guiana in South America; the wine
    // map shows only metropolitan France (and Corsica).
    if (g.id === "250" && ring(p[0])[0][0] < -20) continue;
    p.forEach((r, ri) => {
      const pts = ring(r).map(toSvg);
      // Russia and Fiji cross the date line: where an outline jumps from one
      // edge of the map to the other, start a new piece instead of drawing a
      // line across the world.
      let piece = [pts[0]];
      const pieces = [piece];
      for (let i = 1; i < pts.length; i++) {
        if (Math.abs(pts[i][0] - pts[i - 1][0]) > 300) pieces.push((piece = []));
        piece.push(pts[i]);
      }
      for (const p of pieces) if (p.length > 1) d += "M" + p.map((q) => q.join(",")).join("L") + "Z";
      // The largest outer ring gives the label point.
      if (ri === 0) {
        const xs = pts.map((q) => +q[0]), ys = pts.map((q) => +q[1]);
        const area = (Math.max(...xs) - Math.min(...xs)) * (Math.max(...ys) - Math.min(...ys));
        if (!best || area > best.area) best = { area, at: [Math.round((Math.min(...xs) + Math.max(...xs)) / 2), Math.round((Math.min(...ys) + Math.max(...ys)) / 2)] };
      }
    });
  }
  return { id: g.id, name: g.properties.name, d, label: best?.at ?? null };
});

const header = `// Generated by scripts/build-world.mjs; do not edit by hand.
// Country outlines from Natural Earth (public domain), 1:110m, via the
// world-atlas package: Copyright 2013-2019 Michael Bostock, ISC licence
// ("Permission to use, copy, modify, and/or distribute this software for any
// purpose with or without fee is hereby granted, provided that the above
// copyright notice and this permission notice appear in all copies.").
// Equal Earth projection, Antarctica left out.
`;
writeFileSync(new URL("../src/data/world-map.js", import.meta.url),
  header + `export const WORLD_VIEWBOX = "0 0 ${W} ${H}";\nexport const WORLD_COUNTRIES = ${JSON.stringify(countries)};\n`);
console.log(`${countries.length} countries, viewBox 0 0 ${W} ${H}`);
